#!/usr/bin/env node
"use strict";

/**
 * Build-time copy of packages/core runtime contract assets into apps/mobile/assets/.
 * apps/mobile/assets/{data,i18n,fonts}/ are build artifacts (see apps/mobile/.gitignore)
 * regenerated by this script before `expo start` / `expo prebuild` / `expo run:*`
 * (Issue #223 Phase 5, mirrors apps/web/scripts/copy-core-assets.js).
 *
 * `assets/audio/{ga,rp}/` is NOT populated by this script — bundled TTS mp3s are
 * generated by `tools/tts/gen_tts_batch.py` (#EPIC-05) and wired in separately.
 *
 * Font conversion (Issue #224 Phase 6): `packages/core/fonts/DoulosSIL-Regular.woff2`
 * is a WOFF2 (web font). React Native's native text renderer (CoreText on iOS /
 * `Typeface` on Android) does not reliably load raw WOFF2 via `expo-font`'s
 * `useFonts` — both platforms expect TTF/OTF. Since `packages/core` is
 * read-only-consume (cannot add a `.ttf` there), this script decompresses the
 * WOFF2 into a mobile-only derived `DoulosSIL-Regular.ttf` using `wawoff2`
 * (pure-JS WOFF2->TTF, no native build step) so `apps/mobile/src/fonts/loadFonts.ts`
 * can load a natively-supported format.
 */

const fs = require("fs");
const path = require("path");
const { decompress } = require("wawoff2");

const MOBILE_ROOT = path.resolve(__dirname, "..");
const REPO_ROOT = path.resolve(__dirname, "..", "..", "..");
const CORE_DIR = path.join(REPO_ROOT, "packages", "core");
const ASSETS_DIR = path.join(MOBILE_ROOT, "assets");

function copyFile(src, dest) {
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(src, dest);
  console.log("Copied", path.relative(REPO_ROOT, src), "->", path.relative(REPO_ROOT, dest));
}

function copyJsonFilesInDir(srcDir, destDir) {
  if (!fs.existsSync(srcDir)) return;
  for (const entry of fs.readdirSync(srcDir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      copyJsonFilesInDir(path.join(srcDir, entry.name), path.join(destDir, entry.name));
    } else if (entry.isFile() && entry.name.endsWith(".json")) {
      copyFile(path.join(srcDir, entry.name), path.join(destDir, entry.name));
    }
  }
}

async function convertWoff2ToTtf(srcWoff2, destTtf) {
  const woff2Buffer = fs.readFileSync(srcWoff2);
  const ttfBuffer = await decompress(woff2Buffer);
  fs.mkdirSync(path.dirname(destTtf), { recursive: true });
  fs.writeFileSync(destTtf, Buffer.from(ttfBuffer));
  console.log(
    "Converted",
    path.relative(REPO_ROOT, srcWoff2),
    "(WOFF2) ->",
    path.relative(REPO_ROOT, destTtf),
    "(TTF)"
  );
}

async function main() {
  // packages/core/data/*.json -> apps/mobile/assets/data/*.json
  copyJsonFilesInDir(path.join(CORE_DIR, "data"), path.join(ASSETS_DIR, "data"));

  // packages/core/i18n/*.json + packages/core/i18n/phonemes/*.json -> apps/mobile/assets/i18n/**
  copyJsonFilesInDir(path.join(CORE_DIR, "i18n"), path.join(ASSETS_DIR, "i18n"));

  // packages/core/fonts/*.woff2 -> apps/mobile/assets/fonts/*.ttf (converted, see header comment)
  const fontsDir = path.join(CORE_DIR, "fonts");
  if (fs.existsSync(fontsDir)) {
    for (const entry of fs.readdirSync(fontsDir, { withFileTypes: true })) {
      if (entry.isFile() && entry.name.endsWith(".woff2")) {
        const destName = entry.name.replace(/\.woff2$/, ".ttf");
        await convertWoff2ToTtf(
          path.join(fontsDir, entry.name),
          path.join(ASSETS_DIR, "fonts", destName)
        );
      }
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
